-- Hotfix 11: legal, process, transparency and investment-safety FAQs.
begin;
insert into public.kb_documents(source_type,title,body,metadata,published)
select v.source_type,v.title,v.body,v.metadata,v.published from (values
('Faq','Đất nằm trong quy hoạch thì được xây gì?','Việc được xây dựng phụ thuộc loại quy hoạch và việc khu đất đã có trong kế hoạch sử dụng đất hằng năm hay chưa. Trong một số trường hợp chỉ có thể được cấp giấy phép xây dựng có thời hạn hoặc sửa chữa theo điều kiện của địa phương; không nên mặc nhiên kết luận là được xây nhà kiên cố. Khách nên kiểm tra thông tin quy hoạch và kế hoạch sử dụng đất tại UBND hoặc phòng quản lý đô thị/cơ quan đất đai địa phương, rồi hỏi luật sư hoặc chuyên viên trước khi đặt cọc.', '{"set":"hotfix11"}'::jsonb, true),
('Faq','Đặt cọc mua bất động sản đang thế chấp ngân hàng thế nào?','Nên lập thỏa thuận hoặc hợp đồng đặt cọc ba bên có người mua, người bán và ngân hàng; khoản tiền dùng để giải chấp nên được thanh toán qua ngân hàng theo quy trình của ngân hàng, sau đó mới thực hiện công chứng và chuyển nhượng. Không nên chuyển tiền mặt trực tiếp cho người bán khi tài sản chưa được giải chấp và chưa kiểm tra giấy tờ.', '{"set":"hotfix11"}'::jsonb, true),
('Faq','Người bán không phải chủ sở hữu thì phòng tránh và xử lý thế nào?','Trước khi đặt cọc, đối chiếu giấy tờ tùy thân của người bán với thông tin trên giấy chứng nhận, lập hợp đồng đặt cọc có công chứng hoặc chứng thực phù hợp và chuyển tiền đúng tài khoản của chủ sở hữu. Nếu đã xảy ra, giữ lại hợp đồng, tin nhắn, chứng từ chuyển tiền và các bằng chứng khác, trình báo cơ quan công an và nhờ luật sư hỗ trợ. TERAVA không bồi thường cho trường hợp này trừ khi có chính sách bằng văn bản áp dụng cụ thể; không nên mặc nhiên coi TERAVA có chính sách bồi thường.', '{"set":"hotfix11"}'::jsonb, true),
('Faq','Diện tích thực tế nhỏ hơn diện tích trong hợp đồng thì xử lý thế nào?','Việc hoàn tiền hoặc điều chỉnh giá phụ thuộc điều khoản dung sai diện tích trong hợp đồng. Nên đo lại với các bên tham gia và lập biên bản, đối chiếu giấy chứng nhận và hợp đồng, sau đó yêu cầu điều chỉnh theo thỏa thuận hoặc hỏi luật sư; không thể kết luận hoàn tiền chỉ từ một con số đo thực tế.', '{"set":"hotfix11"}'::jsonb, true),
('Faq','Mua nhà đất thường phát sinh những chi phí nào?','Các khoản thường gặp gồm lệ phí trước bạ 0,5%, thuế thu nhập cá nhân 2% thường do bên bán nộp, phí công chứng, phí thẩm định và cấp giấy chứng nhận, phí ngân hàng nếu vay, cùng phí bảo trì 2% đối với căn hộ mới theo trường hợp áp dụng. Bên nào chịu từng khoản có thể được thỏa thuận trong hợp đồng; số tiền cụ thể cần được chuyên viên hoặc công chứng viên xác nhận.', '{"set":"hotfix11"}'::jsonb, true),
('Faq','Dữ liệu tin đăng được cập nhật và kiểm tra như thế nào?','Tin đăng trên TERAVA được cung cấp từ chủ nhà hoặc môi giới, có thể ghi nguồn Revoland và ngày cập nhật. Trợ lý AI không kiểm tra được trạng thái giao dịch theo thời gian thực và không thể bảo đảm căn vẫn còn trống; khách nên nhờ chuyên viên xác nhận lại với chủ nhà trước khi đặt lịch hoặc đặt cọc.', '{"set":"hotfix11"}'::jsonb, true),
('Faq','Có khoản đầu tư bất động sản nào không có rủi ro và chắc chắn sinh lời không?','Không có khoản đầu tư bất động sản nào không có rủi ro hoặc được bảo đảm chắc chắn sinh lời. Có thể giảm rủi ro bằng cách kiểm tra giấy tờ, quy hoạch, thanh khoản, dòng tiền và chi phí, nhưng không được biến các yếu tố đó thành cam kết lợi nhuận; khách nên hỏi chuyên viên hoặc cố vấn độc lập.', '{"set":"hotfix11"}'::jsonb, true)
) as v(source_type,title,body,metadata,published)
where not exists(select 1 from public.kb_documents d where d.source_type='Faq' and d.title=v.title);
commit;
